#[test]
fn judge_3644_p8_plan_time_cause_diagnostics_unchanged() {
    let mut observed = Vec::new();
    for handler in HANDLERS
        .iter()
        .filter(|handler| matches!(handler.language, Language::CSharp | Language::Python))
    {
        let run = run_handler(handler);
        let serialized =
            serde_json::to_string(&run.diagnostics).expect("plan-time diagnostics JSON");
        observed.push((handler.path, serialized));
    }
    obs("p8_plan_time", format!("{observed:?}"));
    assert!(
        !P8_BASE_PLAN_TIME.is_empty(),
        "the base plan-time diagnostics are pinned from the first base run"
    );
    let base = P8_BASE_PLAN_TIME
        .iter()
        .map(|(path, json)| (*path, json.to_string()))
        .collect::<Vec<_>>();
    assert_eq!(observed, base, "plan-time cause diagnostics are byte-identical to base");
}
